int is_cwe(char *str)
{
    if (strlen(str)!= CWE_MAX_LEN)
        return 0;

    if (str[0]!= 'C' || str[1]!= 'W' || str[2]!= 'E' || str[3]!= '-')
        return 0;

    int i;
    for (i = 4; i < CWE_MAX_LEN; i++)
    {
        if (!isdigit(str[i]))
            return 0;
    }

    return 1;
}

